-- Dumping structure for table total_parking.block
CREATE TABLE IF NOT EXISTS `block` (
  `block_id` smallint unsigned NOT NULL AUTO_INCREMENT,
  `zone_id` tinyint unsigned NOT NULL,
  `block_no` smallint unsigned NOT NULL,
  `kind` varchar(16) NOT NULL,
  `slot_count` tinyint unsigned NOT NULL,
  `bay_length_mm` int DEFAULT NULL,
  `max_width_mm` int DEFAULT NULL,
  `max_height_mm` int DEFAULT NULL,
  `tier_count` tinyint unsigned DEFAULT NULL,
  `column_count` tinyint unsigned DEFAULT NULL,
  `origin_x` smallint DEFAULT NULL,
  `origin_y` smallint DEFAULT NULL,
  `width_units` smallint DEFAULT NULL,
  `height_units` smallint DEFAULT NULL,
  `led_panel_id` varchar(32) DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `map_x` smallint DEFAULT NULL COMMENT 'toa do X tren plan_map.jpg (viewBox 1200x1167)',
  `map_y` smallint DEFAULT NULL COMMENT 'toa do Y tren plan_map.jpg (viewBox 1200x1167)',
  PRIMARY KEY (`block_id`),
  UNIQUE KEY `uq_block_no` (`block_no`),
  KEY `ix_block_zone` (`zone_id`,`is_active`),
  KEY `ix_block_bay` (`kind`,`bay_length_mm`,`is_active`),
  CONSTRAINT `fk_block_zone` FOREIGN KEY (`zone_id`) REFERENCES `zone` (`zone_id`),
  CONSTRAINT `ck_block_kind` CHECK ((`kind` in (_utf8mb4'Mechanical',_utf8mb4'Ground')))
) ENGINE=InnoDB AUTO_INCREMENT=251 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

