CREATE TABLE IF NOT EXISTS `parking_session` (
  `session_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `card_id` int unsigned DEFAULT NULL,
  `event_id` varchar(48) DEFAULT NULL,
  `plate` varchar(16) DEFAULT NULL,
  `status` varchar(16) NOT NULL,
  `zone_id` tinyint unsigned DEFAULT NULL,
  `block_id` smallint unsigned DEFAULT NULL,
  `slot_id` int unsigned DEFAULT NULL,
  `assign_expires_at` datetime(3) DEFAULT NULL,
  `created_at` datetime(3) NOT NULL,
  `updated_at` datetime(3) NOT NULL,
  `parked_at` datetime(3) DEFAULT NULL,
  `completed_at` datetime(3) DEFAULT NULL,
  `error_code` varchar(32) DEFAULT NULL,
  `error_message` varchar(255) DEFAULT NULL,
  `active_card_id` int unsigned GENERATED ALWAYS AS (if((`status` in (_utf8mb4'ASSIGNED',_utf8mb4'ENTERING',_utf8mb4'PARKING',_utf8mb4'PARKED',_utf8mb4'RETRIEVING')),`card_id`,NULL)) VIRTUAL,
  `active_slot_id` int unsigned GENERATED ALWAYS AS (if((`status` in (_utf8mb4'ASSIGNED',_utf8mb4'ENTERING',_utf8mb4'PARKING',_utf8mb4'PARKED',_utf8mb4'RETRIEVING')),`slot_id`,NULL)) VIRTUAL,
  PRIMARY KEY (`session_id`),
  UNIQUE KEY `uq_session_active_card` (`active_card_id`),
  UNIQUE KEY `uq_session_active_slot` (`active_slot_id`),
  KEY `ix_session_status` (`status`,`updated_at`),
  KEY `ix_session_block` (`block_id`,`status`),
  KEY `ix_session_zone` (`zone_id`,`status`),
  KEY `ix_session_card` (`card_id`,`created_at`),
  KEY `fk_session_slot` (`slot_id`),
  KEY `fk_session_event` (`event_id`),
  CONSTRAINT `fk_session_block` FOREIGN KEY (`block_id`) REFERENCES `block` (`block_id`),
  CONSTRAINT `fk_session_card` FOREIGN KEY (`card_id`) REFERENCES `parking_card` (`card_id`),
  CONSTRAINT `fk_session_event` FOREIGN KEY (`event_id`) REFERENCES `vehicle_event` (`event_id`),
  CONSTRAINT `fk_session_slot` FOREIGN KEY (`slot_id`) REFERENCES `parking_slot` (`slot_id`),
  CONSTRAINT `fk_session_zone` FOREIGN KEY (`zone_id`) REFERENCES `zone` (`zone_id`),
  CONSTRAINT `ck_session_status` CHECK ((`status` in (_utf8mb4'NEW',_utf8mb4'ASSIGNED',_utf8mb4'ENTERING',_utf8mb4'PARKING',_utf8mb4'PARKED',_utf8mb4'RETRIEVING',_utf8mb4'COMPLETED',_utf8mb4'CANCELLED',_utf8mb4'ERROR',_utf8mb4'TIMEOUT')))
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

