-- Dumping structure for table total_parking.vehicle_profile
CREATE TABLE IF NOT EXISTS `vehicle_profile` (
  `event_id` varchar(48) NOT NULL,
  `classified_at` datetime(3) NOT NULL,
  `rejected` tinyint(1) NOT NULL DEFAULT '0',
  `reject_reason` varchar(255) DEFAULT NULL,
  `requires_manual` tinyint(1) NOT NULL DEFAULT '0',
  `manual_reason` varchar(255) DEFAULT NULL,
  `lane` varchar(16) NOT NULL,
  `weight_class` varchar(8) NOT NULL,
  `required_pallet_kg` int DEFAULT NULL,
  `estimated_loaded_kg` int DEFAULT NULL,
  `effective_width_mm` int DEFAULT NULL,
  PRIMARY KEY (`event_id`),
  KEY `ix_vehicle_profile_class` (`weight_class`,`lane`),
  CONSTRAINT `fk_vehicle_profile_event` FOREIGN KEY (`event_id`) REFERENCES `vehicle_event` (`event_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

