-- Dumping structure for table total_parking.vehicle_routing
CREATE TABLE IF NOT EXISTS `vehicle_routing` (
  `event_id` varchar(48) NOT NULL,
  `decided_at` datetime(3) NOT NULL,
  `zone_id` tinyint unsigned DEFAULT NULL,
  `outcome` varchar(16) NOT NULL,
  `reason` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`event_id`),
  KEY `ix_vehicle_routing_decided` (`decided_at`),
  KEY `ix_vehicle_routing_zone` (`zone_id`,`decided_at`),
  CONSTRAINT `fk_vehicle_routing_event` FOREIGN KEY (`event_id`) REFERENCES `vehicle_event` (`event_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_vehicle_routing_zone` FOREIGN KEY (`zone_id`) REFERENCES `zone` (`zone_id`),
  CONSTRAINT `ck_vehicle_routing_outcome` CHECK ((`outcome` in (_utf8mb4'ROUTED',_utf8mb4'NO_CAPACITY',_utf8mb4'NO_DATA',_utf8mb4'REJECTED',_utf8mb4'MANUAL')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

